1	package com.example.starter.cems;
2	
3	import java.math.BigDecimal;
4	import java.sql.PreparedStatement;
5	import java.sql.Statement;
6	import java.sql.Timestamp;
7	import java.sql.Types;
8	import java.time.LocalDateTime;
9	import java.util.List;
10	import java.util.Map;
11	
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.jdbc.support.GeneratedKeyHolder;
15	import org.springframework.jdbc.support.KeyHolder;
16	import org.springframework.stereotype.Repository;
17	
18	/**
19	 * 数据访问层：全部 SQL 均参数化；唯一约束承担“读数去重、执行中限排令唯一受理”等并发边界。
20	 */
21	@Repository
22	public class CemsRepository {
23	
24	    private final JdbcTemplate jdbc;
25	
26	    public CemsRepository(JdbcTemplate jdbc) {
27	        this.jdbc = jdbc;
28	    }
29	
30	    // ---------------- 排口 ----------------
31	
32	    /** 登记排口；排口编码重复由唯一约束拒绝。 */
33	    public long insertOutlet(String code, String name, BigDecimal dailyLimit, BigDecimal hourlyLimit,
34	                             String unit, LocalDateTime now) {
35	        KeyHolder keyHolder = new GeneratedKeyHolder();
36	        jdbc.update(con -> {
37	            PreparedStatement ps = con.prepareStatement(
38	                    "INSERT INTO discharge_outlet(outlet_code, outlet_name, status, daily_limit, hourly_limit, "
39	                            + "limit_unit, created_at, updated_at) VALUES (?, ?, 'REGISTERED', ?, ?, ?, ?, ?)",
40	                    Statement.RETURN_GENERATED_KEYS);
41	            ps.setString(1, code);
42	            ps.setString(2, name);
43	            ps.setBigDecimal(3, dailyLimit);
44	            ps.setBigDecimal(4, hourlyLimit);
45	            ps.setString(5, unit);
46	            ps.setTimestamp(6, Timestamp.valueOf(now));
47	            ps.setTimestamp(7, Timestamp.valueOf(now));
48	            return ps;
49	        }, keyHolder);
50	        return keyHolder.getKey().longValue();
51	    }
52	
53	    public Map<String, Object> findOutlet(String code) {
54	        List<Map<String, Object>> rows = jdbc.queryForList(
55	                "SELECT * FROM discharge_outlet WHERE outlet_code = ?", code);
56	        return rows.isEmpty() ? null : rows.get(0);
57	    }
58	
59	    /** 排口进入在线监测（许可登记后首次接入监测数据时调用）。 */
60	    public void markMonitoring(String code, LocalDateTime now) {
61	        jdbc.update("UPDATE discharge_outlet SET status = 'MONITORING', updated_at = ? "
62	                + "WHERE outlet_code = ? AND status = 'REGISTERED'", Timestamp.valueOf(now), code);
63	    }
64	
65	    public void updateOutletStatus(String code, String status, LocalDateTime now) {
66	        jdbc.update("UPDATE discharge_outlet SET status = ?, updated_at = ? WHERE outlet_code = ?",
67	                status, Timestamp.valueOf(now), code);
68	    }
69	
70	    public int archiveOutlet(String code, LocalDateTime archivedAt) {
71	        return jdbc.update(
72	                "UPDATE discharge_outlet SET status = 'ARCHIVED', archived_at = ?, updated_at = ? "
73	                        + "WHERE outlet_code = ? AND status <> 'ARCHIVED'",
74	                Timestamp.valueOf(archivedAt), Timestamp.valueOf(archivedAt), code);
75	    }
76	
77	    // ---------------- 监测读数 ----------------
78	
79	    /**
80	     * 写入小时均值；按“排口＋时段”唯一约束去重。
81	     * @return true 新写入；false 该整点读数已存在（去重）
82	     */
83	    public boolean insertHourlyReading(String code, LocalDateTime hour, BigDecimal value, LocalDateTime now) {
84	        try {
85	            jdbc.update("INSERT INTO monitor_reading(outlet_code, period_type, period_start, avg_value, "
86	                    + "sample_count, created_at) VALUES (?, 'HOUR', ?, ?, 1, ?)",
87	                    code, Timestamp.valueOf(hour), value, Timestamp.valueOf(now));
88	            return true;
89	        } catch (DuplicateKeyException e) {
90	            return false;
91	        }
92	    }
93	
94	    /** 写入日均值；按“排口＋日期”唯一约束去重。 */
95	    public boolean insertDailyReading(String code, LocalDateTime dayStart, BigDecimal value, LocalDateTime now) {
96	        try {
97	            jdbc.update("INSERT INTO monitor_reading(outlet_code, period_type, period_start, avg_value, "
98	                    + "sample_count, created_at) VALUES (?, 'DAY', ?, ?, 1, ?)",
99	                    code, Timestamp.valueOf(dayStart), value, Timestamp.valueOf(now));
100	            return true;
101	        } catch (DuplicateKeyException e) {
102	            return false;
103	        }
104	    }
105	
106	    public List<Map<String, Object>> findHourlyReadings(String code) {
107	        return jdbc.queryForList(
108	                "SELECT * FROM monitor_reading WHERE outlet_code = ? AND period_type = 'HOUR' "
109	                        + "ORDER BY period_start", code);
110	    }
111	
112	    public List<Map<String, Object>> findDailyReadings(String code) {
113	        return jdbc.queryForList(
114	                "SELECT * FROM monitor_reading WHERE outlet_code = ? AND period_type = 'DAY' "
115	                        + "ORDER BY period_start", code);
116	    }
117	
118	    // ---------------- 超标标记 ----------------
119	
120	    public long insertMark(String code, String markType, LocalDateTime periodStart, LocalDateTime periodEnd,
121	                           BigDecimal limitValue, BigDecimal actualValue, int chainIndex,
122	                           String requestId, String status, LocalDateTime now) {
123	        KeyHolder keyHolder = new GeneratedKeyHolder();
124	        jdbc.update(con -> {
125	            PreparedStatement ps = con.prepareStatement(
126	                    "INSERT INTO exceedance_mark(outlet_code, mark_type, period_start, period_end, limit_value, "
127	                            + "actual_value, chain_index, request_id, status, created_at) "
128	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
129	                    Statement.RETURN_GENERATED_KEYS);
130	            ps.setString(1, code);
131	            ps.setString(2, markType);
132	            ps.setTimestamp(3, Timestamp.valueOf(periodStart));
133	            ps.setTimestamp(4, Timestamp.valueOf(periodEnd));
134	            ps.setBigDecimal(5, limitValue);
135	            ps.setBigDecimal(6, actualValue);
136	            ps.setInt(7, chainIndex);
137	            if (requestId == null) {
138	                ps.setNull(8, Types.VARCHAR);
139	            } else {
140	                ps.setString(8, requestId);
141	            }
142	            ps.setString(9, status);
143	            ps.setTimestamp(10, Timestamp.valueOf(now));
144	            return ps;
145	        }, keyHolder);
146	        return keyHolder.getKey().longValue();
147	    }
148	
149	    public Map<String, Object> findDailyMark(String code, LocalDateTime dayStart) {
150	        List<Map<String, Object>> rows = jdbc.queryForList(
151	                "SELECT * FROM exceedance_mark WHERE outlet_code = ? AND mark_type = 'DAILY_AVG' AND period_start = ?",
152	                code, Timestamp.valueOf(dayStart));
153	        return rows.isEmpty() ? null : rows.get(0);
154	    }
155	
156	    public Map<String, Object> findHourlyMark(String code, LocalDateTime hour) {
157	        List<Map<String, Object>> rows = jdbc.queryForList(
158	                "SELECT * FROM exceedance_mark WHERE outlet_code = ? AND mark_type = 'HOURLY_AVG' AND period_start = ?",
159	                code, Timestamp.valueOf(hour));
160	        return rows.isEmpty() ? null : rows.get(0);
161	    }
162	
163	    public List<Map<String, Object>> findHourlyMarks(String code) {
164	        return jdbc.queryForList(
165	                "SELECT * FROM exceedance_mark WHERE outlet_code = ? AND mark_type = 'HOURLY_AVG' ORDER BY period_start",
166	                code);
167	    }
168	
169	    public List<Map<String, Object>> findDailyMarks(String code) {
170	        return jdbc.queryForList(
171	                "SELECT * FROM exceedance_mark WHERE outlet_code = ? AND mark_type = 'DAILY_AVG' ORDER BY period_start",
172	                code);
173	    }
174	
175	    /** 解除限排时关闭该排口全部生效中的小时超标标记。 */
176	    public int resolveActiveHourlyMarks(String code) {
177	        return jdbc.update(
178	                "UPDATE exceedance_mark SET status = 'RESOLVED' WHERE outlet_code = ? "
179	                        + "AND mark_type = 'HOURLY_AVG' AND status = 'ACTIVE'", code);
180	    }
181	
182	    /** 复算：删除全部小时超标链标记后按读数重建。 */
183	    public int deleteHourlyMarks(String code) {
184	        return jdbc.update("DELETE FROM exceedance_mark WHERE outlet_code = ? AND mark_type = 'HOURLY_AVG'", code);
185	    }
186	
187	    /** 复算：删除全部日均超标标记后按读数重建（幂等请求记录不受影响）。 */
188	    public int deleteDailyMarks(String code) {
189	        return jdbc.update("DELETE FROM exceedance_mark WHERE outlet_code = ? AND mark_type = 'DAILY_AVG'", code);
190	    }
191	
192	    // ---------------- 限排令 ----------------
193	
194	    /**
195	     * 下达限排令；active_slot 唯一约束保证同一排口同时刻仅一个执行中限排令，并发下达唯一受理。
196	     */
197	    public void insertOrder(String orderNo, String code, LocalDateTime triggerPeriodStart,
198	                            LocalDateTime issuedAt, LocalDateTime deadline, String activeSlot) {
199	        jdbc.update("INSERT INTO restriction_order(order_no, outlet_code, status, trigger_period_start, "
200	                        + "issued_at, confirm_deadline, active_slot, created_at, updated_at) "
201	                        + "VALUES (?, ?, 'PENDING_CONFIRM', ?, ?, ?, ?, ?, ?)",
202	                orderNo, code, Timestamp.valueOf(triggerPeriodStart), Timestamp.valueOf(issuedAt),
203	                Timestamp.valueOf(deadline), activeSlot, Timestamp.valueOf(issuedAt), Timestamp.valueOf(issuedAt));
204	    }
205	
206	    public Map<String, Object> findOrder(String orderNo) {
207	        List<Map<String, Object>> rows = jdbc.queryForList(
208	                "SELECT * FROM restriction_order WHERE order_no = ?", orderNo);
209	        return rows.isEmpty() ? null : rows.get(0);
210	    }
211	
212	    /** 查找当前占用执行槽的限排令（待确认/执行中/已升级均占槽，关闭后释放）。 */
213	    public Map<String, Object> findOccupyingOrder(String code) {
214	        List<Map<String, Object>> rows = jdbc.queryForList(
215	                "SELECT * FROM restriction_order WHERE outlet_code = ? AND active_slot IS NOT NULL "
216	                        + "ORDER BY issued_at DESC", code);
217	        return rows.isEmpty() ? null : rows.get(0);
218	    }
219	
220	    public List<Map<String, Object>> findOrders(String code) {
221	        return jdbc.queryForList(
222	                "SELECT * FROM restriction_order WHERE outlet_code = ? ORDER BY issued_at", code);
223	    }
224	
225	    public long countOrders(String code) {
226	        Long c = jdbc.queryForObject("SELECT COUNT(*) FROM restriction_order WHERE outlet_code = ?",
227	                Long.class, code);
228	        return c == null ? 0 : c;
229	    }
230	
231	    /**
232	     * 确认执行：限排生效（PENDING_CONFIRM→ACTIVE）与排放总量冻结基数在同一 UPDATE/同一事务内完成，
233	     * 条件更新保证只有待确认令可受理，返回 0 表示状态已变化（重复确认/已升级/已关闭）。
234	     */
235	    public int confirmOrder(String orderNo, BigDecimal frozenTotalQty, LocalDateTime confirmedAt) {
236	        return jdbc.update("UPDATE restriction_order SET status = 'ACTIVE', frozen_total_qty = ?, "
237	                        + "confirmed_at = ?, active_slot = outlet_code, updated_at = ? "
238	                        + "WHERE order_no = ? AND status = 'PENDING_CONFIRM'",
239	                frozenTotalQty, Timestamp.valueOf(confirmedAt), Timestamp.valueOf(confirmedAt), orderNo);
240	    }
241	
242	    /** 查找全部待确认令（升级巡检用）。 */
243	    public List<Map<String, Object>> findPendingConfirmOrders(String code) {
244	        return jdbc.queryForList(
245	                "SELECT * FROM restriction_order WHERE outlet_code = ? AND status = 'PENDING_CONFIRM' "
246	                        + "ORDER BY issued_at", code);
247	    }
248	
249	    /**
250	     * 超时升级：PENDING_CONFIRM→ESCALATED，同时写入排放总量冻结基数（同事务），返回 0 表示无需升级。
251	     * 条件 confirm_deadline &lt;= now 保证“恰满 2 小时”当刻即升级，早一刻不升级。
252	     */
253	    public int escalateOrder(String orderNo, BigDecimal frozenTotalQty, LocalDateTime now) {
254	        return jdbc.update("UPDATE restriction_order SET status = 'ESCALATED', escalated_at = ?, "
255	                        + "escalate_reason = '确认执行期限届满（下达后恰满2小时未确认），自动升级并联动限产', "
256	                        + "frozen_total_qty = ?, active_slot = outlet_code, "
257	                        + "updated_at = ? WHERE order_no = ? AND status = 'PENDING_CONFIRM' AND confirm_deadline <= ?",
258	                Timestamp.valueOf(now), frozenTotalQty, Timestamp.valueOf(now), orderNo, Timestamp.valueOf(now));
259	    }
260	
261	    /** 汇总截至某时刻全部小时均值作为排放总量冻结基数（合成单位：mg/L·小时累计）。 */
262	    public BigDecimal sumHourlyValuesUpTo(String code, LocalDateTime upTo) {
263	        BigDecimal sum = jdbc.queryForObject(
264	                "SELECT COALESCE(SUM(avg_value), 0) FROM monitor_reading WHERE outlet_code = ? "
265	                        + "AND period_type = 'HOUR' AND period_start <= ?",
266	                BigDecimal.class, code, Timestamp.valueOf(upTo));
267	        return sum == null ? BigDecimal.ZERO : sum;
268	    }
269	
270	    /** 按触发时段查找限排令（复算补建用）。 */
271	    public Map<String, Object> findOrderByTrigger(String code, LocalDateTime triggerPeriodStart) {
272	        List<Map<String, Object>> rows = jdbc.queryForList(
273	                "SELECT * FROM restriction_order WHERE outlet_code = ? AND trigger_period_start = ?",
274	                code, Timestamp.valueOf(triggerPeriodStart));
275	        return rows.isEmpty() ? null : rows.get(0);
276	    }
277	
278	    /** 关闭限排令并释放执行槽；仅执行中/已升级令可关闭，复测信息与关闭同事务写入。 */
279	    public int closeOrder(String orderNo, LocalDateTime retestPeriodStart, LocalDateTime retestPeriodEnd,
280	                          BigDecimal retestValue, String releaseRequestId, LocalDateTime closedAt) {
281	        return jdbc.update("UPDATE restriction_order SET status = 'CLOSED', retest_period_start = ?, "
282	                        + "retest_period_end = ?, retest_value = ?, release_request_id = ?, closed_at = ?, "
283	                        + "active_slot = NULL, updated_at = ? WHERE order_no = ? AND status IN ('ACTIVE', 'ESCALATED')",
284	                Timestamp.valueOf(retestPeriodStart), Timestamp.valueOf(retestPeriodEnd), retestValue,
285	                releaseRequestId, Timestamp.valueOf(closedAt), Timestamp.valueOf(closedAt), orderNo);
286	    }
287	
288	    // ---------------- 联动限产 ----------------
