55	    private final CemsClock clock;
56	    private final IdempotencySupport idem;
57	
58	    public CemsService(CemsRepository repo, CemsClock clock, IdempotencySupport idem) {
59	        this.repo = repo;
60	        this.clock = clock;
61	        this.idem = idem;
62	    }
63	
64	    // ---------------- 许可登记 ----------------
