95	    @Transactional
96	    public DailyEvalResult evaluateDaily(DailyEvalRequest req) {
97	        if (req.day() == null) {
98	            throw new IllegalArgumentException("day 不能为空");
99	        }
100	        Map<String, Object> fields = new LinkedHashMap<>();
101	        fields.put("outletCode", req.outletCode());
102	        fields.put("day", req.day().toString());
103	        fields.put("avgValue", req.avgValue());
104	        return replayable(req.requestId(), "DAILY_EVAL", fields, DailyEvalResult.class, () -> doEvaluateDaily(req));
105	    }
