107	    private DailyEvalResult doEvaluateDaily(DailyEvalRequest req) {
108	        String code = requireText(req.outletCode(), "outletCode");
109	        requireNonNullNonNegative(req.avgValue(), "avgValue");
110	        Map<String, Object> outlet = loadOutlet(code);
111	        BigDecimal dailyLimit = bd(outlet.get("daily_limit"));
112	        LocalDateTime dayStart = req.day().atStartOfDay();
113	        LocalDateTime dayEnd = dayStart.plusDays(1);
114	        LocalDateTime now = clock.now();
115	
116	        if (isArchived(outlet)) {
117	            // 归档为终态：迟到监测数据只记迟到事件，不参与评价、不改变排口状态。
118	            repo.insertEvent(code, "LATE_READING", now, true,
119	                    "DAY " + req.day() + " avgValue=" + req.avgValue());
120	            return new DailyEvalResult(req.requestId(), code, req.day(), req.avgValue(),
121	                    dailyLimit, false, true, null);
122	        }
123	
124	        repo.markMonitoring(code, now);
125	        boolean fresh = repo.insertDailyReading(code, dayStart, req.avgValue(), now);
126	        if (!fresh) {
127	            Map<String, Object> existingReadings = repo.findDailyReadings(code).stream()
128	                    .filter(r -> dayStart.equals(lt(r.get("period_start"))))
129	                    .findFirst().orElse(null);
130	            if (existingReadings != null && req.avgValue().compareTo(bd(existingReadings.get("avg_value"))) != 0) {
131	                throw new ConflictException("排口＋日期读数已存在且数值不同: " + code + " " + req.day());
132	            }
133	        }
134	        boolean exceeded = req.avgValue().compareTo(dailyLimit) > 0;
135	        Long markId = null;
136	        Map<String, Object> mark = repo.findDailyMark(code, dayStart);
137	        if (exceeded && mark == null) {
138	            markId = repo.insertMark(code, "DAILY_AVG", dayStart, dayEnd, dailyLimit, req.avgValue(),
139	                    0, req.requestId(), "ACTIVE", now);
140	            repo.insertEvent(code, "MARK", now, false,
141	                    "DAILY_AVG actual=" + req.avgValue() + " limit=" + dailyLimit);
142	        } else if (mark != null) {
143	            markId = ((Number) mark.get("id")).longValue();
144	        }
145	        if (fresh) {
146	            repo.insertEvent(code, "READING", now, false,
147	                    "DAY " + req.day() + " avgValue=" + req.avgValue());
148	        }
149	        return new DailyEvalResult(req.requestId(), code, req.day(), req.avgValue(),
150	                dailyLimit, exceeded, false, markId);
151	    }
