222	    /**
223	     * 按全部小时读数重算连续超标链并重建小时标记：恰连续 3 次（链序号=3）为触发点。
224	     * 相邻整点、逐时连续且均超标才累计链序号；任一合格读数或中间缺测都使链重置。
225	     * 已随限排令复测合格而解除（RESOLVED）的历史标记，复算后仍保持 RESOLVED。
226	     */
227	    private List<ChainPoint> rebuildHourlyChain(String code, BigDecimal hourlyLimit) {
228	        List<Map<String, Object>> readings = repo.findHourlyReadings(code);
229	        Map<String, String> priorStatus = new LinkedHashMap<>();
230	        for (Map<String, Object> m : repo.findHourlyMarks(code)) {
231	            priorStatus.put(lt(m.get("period_start")).toString(), (String) m.get("status"));
232	        }
233	        List<ChainPoint> points = new ArrayList<>();
234	        LocalDateTime prevHour = null;
235	        int streak = 0;
236	        for (Map<String, Object> r : readings) {
237	            LocalDateTime hour = lt(r.get("period_start"));
238	            boolean exceeded = bd(r.get("avg_value")).compareTo(hourlyLimit) > 0;
239	            if (exceeded) {
240	                streak = (prevHour != null && hour.equals(prevHour.plusHours(1)) && streak > 0)
241	                        ? streak + 1 : 1;
242	            } else {
243	                streak = 0;
244	            }
245	            points.add(new ChainPoint(hour, exceeded, streak));
246	            prevHour = hour;
247	        }
248	        repo.deleteHourlyMarks(code);
249	        LocalDateTime now = clock.now();
250	        for (ChainPoint p : points) {
251	            if (p.exceeded()) {
252	                BigDecimal value = readings.stream()
253	                        .filter(r -> p.hour().equals(lt(r.get("period_start"))))
254	                        .map(r -> bd(r.get("avg_value"))).findFirst().orElseThrow();
255	                String markStatus = "RESOLVED".equals(priorStatus.get(p.hour().toString()))
256	                        ? "RESOLVED" : "ACTIVE";
257	                repo.insertMark(code, "HOURLY_AVG", p.hour(), p.hour().plusHours(1),
258	                        hourlyLimit, value, p.streak(), null, markStatus, now);
259	            }
260	        }
261	        return points;
262	    }
