266	    @Transactional
267	    public GapResult checkGap(GapCheckRequest req) {
268	        String code = requireText(req.outletCode(), "outletCode");
269	        if (req.missingFrom() == null || req.missingTo() == null) {
270	            throw new IllegalArgumentException("missingFrom/missingTo 不能为空");
271	        }
272	        if (!req.missingTo().isAfter(req.missingFrom())) {
273	            throw new IllegalArgumentException("missingTo 必须晚于 missingFrom");
274	        }
275	        Map<String, Object> outlet = loadOutlet(code);
276	        if (isArchived(outlet)) {
277	            throw new ConflictException("排口已归档（终态），不再督办数据缺失: " + code);
278	        }
279	        long minutes = Duration.between(req.missingFrom(), req.missingTo()).toMinutes();
280	        boolean marked = minutes > GAP_THRESHOLD_MINUTES;
281	        LocalDateTime now = clock.now();
282	        if (marked) {
283	            boolean created = repo.insertGap(code, req.missingFrom(), req.missingTo(),
284	                    (int) minutes, "SUPERVISED", now);
285	            if (created) {
286	                repo.insertEvent(code, "GAP_SUPERVISE", now, false,
287	                        "gap=" + minutes + "min [" + req.missingFrom() + "," + req.missingTo() + ")");
288	            }
289	        }
290	        return new GapResult(code, req.missingFrom(), req.missingTo(), minutes, marked,
291	                marked ? now : null);
292	    }
