294	    // ---------------- 限排令确认执行（基数冻结同事务） ----------------
295	
296	    @Transactional
297	    public Receipt confirmOrder(ConfirmOrderRequest req) {
298	        Map<String, Object> fields = new LinkedHashMap<>();
299	        fields.put("orderNo", req.orderNo());
300	        return replayable(req.requestId(), "CONFIRM", fields, Receipt.class, () -> doConfirm(req));
301	    }
302	
303	    private Receipt doConfirm(ConfirmOrderRequest req) {
304	        String orderNo = requireText(req.orderNo(), "orderNo");
305	        Map<String, Object> order = loadOrder(orderNo);
306	        String code = (String) order.get("outlet_code");
307	        Map<String, Object> outlet = loadOutlet(code);
308	        if (isArchived(outlet)) {
309	            throw new ConflictException("排口已归档，不能再确认限排令: " + code);
310	        }
311	        String status = (String) order.get("status");
312	        LocalDateTime now = clock.now();
313	        return switch (status) {
314	            case "CLOSED" -> throw new ConflictException("限排令已关闭，不能重复确认: " + orderNo);
315	            case "ACTIVE" -> throw new ConflictException("限排令已确认执行: " + orderNo);
316	            case "ESCALATED" -> throw new ConflictException("限排令已超期升级，不能再确认: " + orderNo);
317	            default -> {
318	                LocalDateTime deadline = lt(order.get("confirm_deadline"));
319	                if (!now.isBefore(deadline)) {
320	                    throw new ConflictException("已超过确认执行期限（恰满2小时），限排令应升级: " + orderNo);
321	                }
322	                // 限排生效与排放总量冻结基数在同一 UPDATE/同一事务内完成，不存在“生效而基数未定”。
323	                BigDecimal frozenQty = repo.sumHourlyValuesUpTo(code, now);
324	                int n = repo.confirmOrder(orderNo, frozenQty, now);
325	                if (n == 0) {
326	                    throw new ConflictException("限排令状态已变化，确认未受理: " + orderNo);
327	                }
328	                repo.updateOutletStatus(code, "RESTRICTED", now);
329	                repo.insertEvent(code, "CONFIRM", now, false,
330	                        "orderNo=" + orderNo + " frozenTotalQty=" + frozenQty);
331	                yield new Receipt(req.requestId(), "CONFIRM_RESTRICTION", false);
332	            }
333	        };
334	    }
