336	    // ---------------- 超时升级并联动限产 ----------------
337	
338	    @Transactional
339	    public List<OrderView> escalateSweep(String outletCode) {
340	        Map<String, Object> outlet = loadOutlet(outletCode);
341	        if (isArchived(outlet)) {
342	            throw new ConflictException("排口已归档: " + outletCode);
343	        }
344	        List<OrderView> escalated = new ArrayList<>();
345	        LocalDateTime now = clock.now();
346	        for (Map<String, Object> order : repo.findPendingConfirmOrders(outletCode)) {
347	            String orderNo = (String) order.get("order_no");
348	            LocalDateTime deadline = lt(order.get("confirm_deadline"));
349	            if (!now.isBefore(deadline)) {
350	                BigDecimal frozenQty = repo.sumHourlyValuesUpTo(outletCode, now);
351	                int n = repo.escalateOrder(orderNo, frozenQty, now);
352	                if (n > 0) {
353	                    // 升级与联动限产同事务：升级提交则限产记录必然存在。
354	                    repo.insertProductionCut(orderNo, outletCode, ESCALATION_CUT_RATIO,
355	                            "限排令下达后恰满2小时未确认，联动限产30%", now);
356	                    repo.updateOutletStatus(outletCode, "RESTRICTED", now);
357	                    repo.insertEvent(outletCode, "ESCALATE", now, false,
358	                            "orderNo=" + orderNo + " cutRatio=" + ESCALATION_CUT_RATIO);
359	                    escalated.add(toOrderView(repo.findOrder(orderNo)));
360	                }
361	            }
362	        }
363	        return escalated;
364	    }
