366	    // ---------------- 复测合格解除（关闭同事务） ----------------
367	
368	    @Transactional
369	    public ReleaseResult release(ReleaseRestrictionRequest req) {
370	        Map<String, Object> fields = new LinkedHashMap<>();
371	        fields.put("orderNo", req.orderNo());
372	        fields.put("retestHour", req.retestHour() == null ? null : req.retestHour().toString());
373	        fields.put("retestValue", req.retestValue());
374	        return replayable(req.requestId(), "RELEASE", fields, ReleaseResult.class, () -> doRelease(req));
375	    }
376	
377	    private ReleaseResult doRelease(ReleaseRestrictionRequest req) {
378	        String orderNo = requireText(req.orderNo(), "orderNo");
379	        requireNonNullNonNegative(req.retestValue(), "retestValue");
380	        if (req.retestHour() == null) {
381	            throw new IllegalArgumentException("retestHour 不能为空");
382	        }
383	        Map<String, Object> order = loadOrder(orderNo);
384	        String code = (String) order.get("outlet_code");
385	        Map<String, Object> outlet = loadOutlet(code);
386	        if (isArchived(outlet)) {
387	            throw new ConflictException("排口已归档，不能解除限排令: " + code);
388	        }
389	        String status = (String) order.get("status");
390	        BigDecimal hourlyLimit = bd(outlet.get("hourly_limit"));
391	        LocalDateTime retestHour = req.retestHour().truncatedTo(ChronoUnit.HOURS);
392	        LocalDateTime now = clock.now();
393	        return switch (status) {
394	            case "CLOSED" -> throw new ConflictException("限排令已关闭: " + orderNo);
395	            case "PENDING_CONFIRM" -> throw new ConflictException("限排令尚未确认执行，不能解除: " + orderNo);
396	            default -> {
397	                // 复测合格：含本值达标；不合格不得解除，限排令状态不变。
398	                if (req.retestValue().compareTo(hourlyLimit) > 0) {
399	                    throw new ConflictException("复测小时均值 " + req.retestValue()
400	                            + " 超过限值 " + hourlyLimit + "，复测不合格，不能解除限排");
401	                }
402	                LocalDateTime issuedAt = lt(order.get("issued_at"));
403	                if (!retestHour.isAfter(issuedAt.truncatedTo(ChronoUnit.HOURS))) {
404	                    throw new IllegalArgumentException("复测时段必须晚于限排令下达时段");
405	                }
406	                boolean freshRetest = repo.insertHourlyReading(code, retestHour, req.retestValue(), now);
407	                if (!freshRetest) {
408	                    Map<String, Object> existing = repo.findHourlyReadings(code).stream()
409	                            .filter(r -> retestHour.equals(lt(r.get("period_start"))))
410	                            .findFirst().orElse(null);
411	                    if (existing != null && req.retestValue().compareTo(bd(existing.get("avg_value"))) != 0) {
412	                        throw new ConflictException("复测时段读数已存在且数值不同: " + retestHour);
413	                    }
414	                }
415	                // 解除限排与限排令关闭在同一事务：任一失败整体回滚。
416	                int n = repo.closeOrder(orderNo, retestHour, retestHour.plusHours(1),
417	                        req.retestValue(), req.requestId(), now);
418	                if (n == 0) {
419	                    throw new ConflictException("限排令状态已变化，解除未受理: " + orderNo);
420	                }
421	                repo.resolveActiveHourlyMarks(code);
422	                repo.updateOutletStatus(code, "MONITORING", now);
423	                repo.insertEvent(code, "RELEASE", now, false,
424	                        "orderNo=" + orderNo + " retestValue=" + req.retestValue());
425	                yield new ReleaseResult(req.requestId(), orderNo, code, "CLOSED", now);
426	            }
427	        };
428	    }
