432	    @Transactional
433	    public ArchiveResult archive(ArchiveOutletRequest req) {
434	        Map<String, Object> fields = new LinkedHashMap<>();
435	        fields.put("outletCode", req.outletCode());
436	        return replayable(req.requestId(), "ARCHIVE", fields, ArchiveResult.class, () -> doArchive(req));
