450	        }
451	        int n = repo.archiveOutlet(code, archivedAt);
452	        if (n == 0) {
453	            throw new ConflictException("排口状态已变化，归档未受理: " + code);
454	        }
455	        repo.insertEvent(code, "ARCHIVE", archivedAt, false, "排口归档（终态）");
456	        return new ArchiveResult(req.requestId(), code, true, archivedAt);
457	    }
