459	    // ---------------- 复算 ----------------
460	
461	    @Transactional
462	    public RecomputeResult recompute(RecomputeRequest req) {
463	        String code = requireText(req.outletCode(), "outletCode");
464	        Map<String, Object> outlet = loadOutlet(code);
465	        if (isArchived(outlet)) {
466	            throw new ConflictException("排口已归档（终态），不能复算: " + code);
467	        }
468	        BigDecimal hourlyLimit = bd(outlet.get("hourly_limit"));
469	        BigDecimal dailyLimit = bd(outlet.get("daily_limit"));
470	        List<String> details = new ArrayList<>();
471	
472	        // 1) 小时超标链标记重建，并对缺失的触发限排记录做补建（不改变既有令状态）。
473	        List<ChainPoint> chain = rebuildHourlyChain(code, hourlyLimit);
474	        int orderCreated = 0;
475	        for (ChainPoint p : chain) {
476	            if (p.streak() == RESTRICTION_STREAK && repo.findOrderByTrigger(code, p.hour()) == null) {
477	                if (repo.findOccupyingOrder(code) == null) {
478	                    String orderNo = issueOrder(code, p.hour(), hourlyLimit, clock.now());
479	                    orderCreated++;
480	                    details.add("补建限排令 " + orderNo + "（触发时段 " + p.hour() + "）");
481	                } else {
482	                    details.add("触发时段 " + p.hour() + " 存在执行中限排令，跳过补建");
483	                }
484	            }
485	        }
486	
487	        // 2) 日均超标标记按日读数重建（保留原标记携带的 requestId）。
488	        Map<String, String> dailyRequestByPeriod = new LinkedHashMap<>();
489	        for (Map<String, Object> m : repo.findDailyMarks(code)) {
490	            Object rid = m.get("request_id");
491	            dailyRequestByPeriod.put(lt(m.get("period_start")).toString(), rid == null ? null : rid.toString());
492	        }
493	        int dailyMarkCount = 0;
494	        repo.deleteDailyMarks(code);
495	        LocalDateTime now = clock.now();
496	        for (Map<String, Object> r : repo.findDailyReadings(code)) {
497	            LocalDateTime dayStart = lt(r.get("period_start"));
498	            BigDecimal value = bd(r.get("avg_value"));
499	            if (value.compareTo(dailyLimit) > 0) {
500	                repo.insertMark(code, "DAILY_AVG", dayStart, dayStart.plusDays(1), dailyLimit, value,
501	                        0, dailyRequestByPeriod.get(dayStart.toString()), "ACTIVE", now);
502	                dailyMarkCount++;
503	            }
504	        }
505	
506	        // 3) 缺失督办按首末读数之间的连续整点缺槽重算：仅连续缺槽严格大于 2 小时才督办。
507	        repo.deleteGaps(code);
508	        int gapCount = rebuildGaps(code, details);
509	
510	        long activeOrderCount = repo.findOrders(code).stream()
511	                .filter(o -> !"CLOSED".equals(o.get("status"))).count();
512	        int hourlyMarkCount = (int) chain.stream().filter(ChainPoint::exceeded).count();
513	        return new RecomputeResult(code, hourlyMarkCount, dailyMarkCount, (int) activeOrderCount,
514	                gapCount, details);
515	    }
516	
517	    /**
518	     * 依据小时读数序列找出连续缺失整点区间，缺失严格大于 2 小时（&gt;120 分钟）才重新登记督办。
519	     */
520	    private int rebuildGaps(String code, List<String> details) {
521	        List<Map<String, Object>> readings = repo.findHourlyReadings(code);
522	        if (readings.size() < 2) {
523	            return 0;
524	        }
525	        int gapCount = 0;
526	        LocalDateTime now = clock.now();
527	        for (int i = 1; i < readings.size(); i++) {
528	            LocalDateTime prev = lt(readings.get(i - 1).get("period_start"));
529	            LocalDateTime cur = lt(readings.get(i).get("period_start"));
530	            long missingHours = ChronoUnit.HOURS.between(prev, cur) - 1;
531	            if (missingHours > 0) {
532	                LocalDateTime gapStart = prev.plusHours(1);
533	                LocalDateTime gapEnd = cur;
534	                long minutes = Duration.between(gapStart, gapEnd).toMinutes();
535	                if (minutes > GAP_THRESHOLD_MINUTES) {
536	                    repo.insertGap(code, gapStart, gapEnd, (int) minutes, "SUPERVISED", now);
537	                    gapCount++;
538	                    details.add("复算缺失督办 " + minutes + " 分钟 [" + gapStart + "," + gapEnd + ")");
539	                }
540	            }
541	        }
542	        return gapCount;
543	    }
544	
545	    // ---------------- 查询 ----------------
546	
547	    @Transactional(readOnly = true)
548	    public OutletView getOutlet(String code) {
549	        return toOutletView(loadOutlet(code));
550	    }
551	
552	    @Transactional(readOnly = true)
553	    public OrderView getOrder(String orderNo) {
554	        return toOrderView(loadOrder(orderNo));
555	    }
556	
557	    @Transactional(readOnly = true)
558	    public List<Map<String, Object>> getEvents(String code) {
559	        loadOutlet(code);
560	        return repo.findEvents(code);
561	    }
562	
563	    // ---------------- 幂等支撑 ----------------
564	
565	    /**
566	     * 幂等执行：指纹覆盖 requestId 与全部业务字段。
567	     * 同键同参返回首次结果；同键异参抛 409 且不执行动作、不改变排口状态。
568	     * 先插入占位行（主键串行化同键并发），业务动作成功后回写结果；动作失败则随事务回滚释放该键。
569	     */
570	    private <T> T replayable(String requestId, String requestType, Map<String, Object> fields,
571	                             Class<T> resultType, Supplier<T> action) {
572	        String rid = requireText(requestId, "requestId");
573	        String fingerprint = idem.fingerprint(rid, fields);
574	        Map<String, Object> existing = repo.findIdempotent(rid);
575	        if (existing != null) {
576	            return replayOrConflict(rid, fingerprint, existing, resultType);
577	        }
578	        while (true) {
579	            if (repo.insertIdempotent(rid, requestType, fingerprint, "", clock.now())) {
580	                T result = action.get();
581	                repo.updateIdempotentResult(rid, idem.toJson(result));
582	                return result;
583	            }
584	            // 同键并发：等待首个事务提交结果；若其回滚（占位行消失）则重新抢占。
585	            Map<String, Object> raced = waitForIdempotentResult(rid);
586	            if (raced != null) {
587	                return replayOrConflict(rid, fingerprint, raced, resultType);
588	            }
589	        }
590	    }
591	
592	    private <T> T replayOrConflict(String rid, String fingerprint, Map<String, Object> row, Class<T> resultType) {
593	        if (!fingerprint.equals(row.get("fingerprint"))) {
594	            throw new ConflictException("requestId=" + rid + " 请求参数与首次调用不一致（409 幂等冲突）");
595	        }
596	        return idem.fromJson((String) row.get("result_json"), resultType);
597	    }
598	
599	    /**
600	     * 并发同键后等待首个事务提交结果（真实并发协调，带超时）。
601	     * @return 已回写结果的幂等行；占位行消失（首个事务回滚）时返回 null 供调用方重新抢占
602	     */
603	    private Map<String, Object> waitForIdempotentResult(String rid) {
604	        long deadlineMillis = System.currentTimeMillis() + 15_000L;
605	        while (true) {
606	            Map<String, Object> row = repo.findIdempotent(rid);
607	            if (row == null) {
608	                return null;
609	            }
610	            if (!"".equals(row.get("result_json"))) {
611	                return row;
612	            }
613	            if (System.currentTimeMillis() >= deadlineMillis) {
614	                throw new ConflictException("requestId=" + rid + " 并发请求等待首次结果超时");
615	            }
616	            try {
617	                Thread.sleep(20L);
618	            } catch (InterruptedException e) {
619	                Thread.currentThread().interrupt();
620	                throw new ConflictException("并发幂等等待被中断");
621	            }
622	        }
623	    }
624	
625	    // ---------------- 公共辅助 ----------------
626	
627	    private Map<String, Object> loadOutlet(String code) {
628	        Map<String, Object> outlet = repo.findOutlet(code);
629	        if (outlet == null) {
630	            throw new NotFoundException("排口不存在: " + code);
631	        }
632	        return outlet;
633	    }
634	
635	    private Map<String, Object> loadOrder(String orderNo) {
636	        Map<String, Object> order = repo.findOrder(orderNo);
637	        if (order == null) {
638	            throw new NotFoundException("限排令不存在: " + orderNo);
639	        }
640	        return order;
641	    }
642	
643	    private boolean isArchived(Map<String, Object> outlet) {
644	        return "ARCHIVED".equals(outlet.get("status"));
645	    }
646	
647	    private static BigDecimal bd(Object value) {
648	        if (value == null) {
649	            return null;
650	        }
651	        return value instanceof BigDecimal b ? b : new BigDecimal(value.toString());
652	    }
653	
654	    private static LocalDateTime lt(Object value) {
655	        if (value == null) {
656	            return null;
657	        }
658	        return value instanceof Timestamp t ? t.toLocalDateTime() : LocalDateTime.parse(value.toString());
659	    }
660	
661	    private static String requireText(String value, String field) {
662	        if (value == null || value.isBlank()) {
663	            throw new IllegalArgumentException(field + " 不能为空");
664	        }
665	        return value;
666	    }
667	
668	    private static void requireNonNullNonNegative(BigDecimal value, String field) {
669	        if (value == null) {
670	            throw new IllegalArgumentException(field + " 不能为空");
671	        }
672	        if (value.signum() < 0) {
673	            throw new IllegalArgumentException(field + " 不能为负数");
674	        }
675	    }
676	
677	    private static OutletView toOutletView(Map<String, Object> o) {
678	        return new OutletView(
679	                (String) o.get("outlet_code"),
680	                (String) o.get("outlet_name"),
681	                (String) o.get("status"),
682	                bd(o.get("daily_limit")),
683	                bd(o.get("hourly_limit")),
684	                (String) o.get("limit_unit"),
685	                lt(o.get("created_at")),
686	                lt(o.get("archived_at")));
687	    }
688	
689	    private static OrderView toOrderView(Map<String, Object> o) {
690	        return new OrderView(
691	                (String) o.get("order_no"),
692	                (String) o.get("outlet_code"),
693	                (String) o.get("status"),
694	                bd(o.get("frozen_total_qty")),
695	                lt(o.get("issued_at")),
696	                lt(o.get("confirm_deadline")),
697	                lt(o.get("confirmed_at")),
698	                lt(o.get("escalated_at")),
699	                (String) o.get("escalate_reason"),
700	                bd(o.get("retest_value")),
701	                lt(o.get("closed_at")));
702	    }
703	
704	    /** 小时连续超标链上的一个计算点。 */
705	    private record ChainPoint(LocalDateTime hour, boolean exceeded, int streak) {
706	    }
707	}
